values
('de.lexicon.core',2,'de','lexicon','Grundwortschatz','Erweiterter kontextbezogener Wortschatz','{"explanation":"Erweiterter, original formulierter Wortschatz mit kontextabhängigen Bedeutungen. Übersetzungen sind Orientierungshilfen; Satzkontext, Register und regionale Variante bleiben entscheidend.","terms":[{"term":"eigentlich","meaning_de":"im Grunde; kann eine Aussage abschwächen oder eine Korrektur einleiten"},{"term":"vielleicht","meaning_de":"möglicherweise; drückt Unsicherheit aus"},{"term":"allerdings","meaning_de":"jedoch; markiert eine Einschränkung oder einen Gegensatz"},{"term":"trotzdem","meaning_de":"dennoch; etwas geschieht trotz eines Hindernisses"},{"term":"während","meaning_de":"zeitgleich mit; kann auch einen Gegensatz einleiten"},{"term":"obwohl","meaning_de":"leitet einen konzessiven Nebensatz ein"},{"term":"deshalb","meaning_de":"aus diesem Grund; markiert eine Folge"},{"term":"sowohl","meaning_de":"gemeinsam mit als auch; Teil der Verbindung sowohl … als auch"},{"term":"weder","meaning_de":"verneint zwei Alternativen in weder … noch"},{"term":"noch","meaning_de":"bis jetzt weiterhin oder zusätzlich; Bedeutung hängt stark vom Kontext ab"},{"term":"Leistung","meaning_de":"erbrachtes Ergebnis oder Fähigkeit in einem bestimmten Bereich"},{"term":"Entwicklung","meaning_de":"Veränderung über einen Zeitraum"},{"term":"Stärke","meaning_de":"ausgeprägte positive Fähigkeit oder Eigenschaft"},{"term":"Schwäche","meaning_de":"Bereich mit erkennbarem Verbesserungsbedarf"},{"term":"Einschätzung","meaning_de":"begründetes, aber möglicherweise unsicheres Urteil"}],"examples":[],"grammar_notes":[],"aliases":["eigentlich","vielleicht","allerdings","trotzdem","während","obwohl","deshalb","sowohl","weder","noch","Leistung","Entwicklung","Stärke","Schwäche","Einschätzung"]}'::jsonb,ARRAY['vocabulary','meaning','context'],'foundational','active','original_authored','messinho_original'),
('en.lexicon.core',2,'en','lexicon','Grundwortschatz','Erweiterter kontextbezogener Wortschatz','{"explanation":"Erweiterter, original formulierter Wortschatz mit kontextabhängigen Bedeutungen. Übersetzungen sind Orientierungshilfen; Satzkontext, Register und regionale Variante bleiben entscheidend.","terms":[{"term":"actually","meaning_de":"tatsächlich; oft Korrektur oder Präzisierung, nicht automatisch aktuell"},{"term":"rather","meaning_de":"eher; vielmehr; kann eine Präferenz oder Einschränkung markieren"},{"term":"although","meaning_de":"obwohl; leitet einen Gegensatz ein"},{"term":"however","meaning_de":"jedoch; markiert einen Kontrast"},{"term":"unless","meaning_de":"es sei denn; wenn nicht"},{"term":"despite","meaning_de":"trotz; leitet einen Gegensatz zu einer Erwartung ein"},{"term":"still","meaning_de":"immer noch; weiterhin; dennoch je nach Kontext"},{"term":"already","meaning_de":"bereits; früher als erwartet oder vor dem Bezugszeitpunkt"},{"term":"yet","meaning_de":"noch; bisher; in Fragen und Verneinungen häufig anders als already"},{"term":"likely","meaning_de":"wahrscheinlich; drückt keine Gewissheit aus"},{"term":"performance","meaning_de":"Leistung oder Darbietung abhängig vom Kontext"},{"term":"development","meaning_de":"Entwicklung über Zeit"},{"term":"strength","meaning_de":"Stärke oder positive Fähigkeit"},{"term":"weakness","meaning_de":"Schwäche oder Verbesserungsbedarf"},{"term":"assessment","meaning_de":"Bewertung oder Einschätzung"}],"examples":[],"grammar_notes":[],"aliases":["actually","rather","although","however","unless","despite","still","already","yet","likely","performance","development","strength","weakness","assessment"]}'::jsonb,ARRAY['vocabulary','meaning','context'],'foundational','active','original_authored','messinho_original'),
('fr.lexicon.core',2,'fr','lexicon','Grundwortschatz','Erweiterter kontextbezogener Wortschatz','{"explanation":"Erweiterter, original formulierter Wortschatz mit kontextabhängigen Bedeutungen. Übersetzungen sind Orientierungshilfen; Satzkontext, Register und regionale Variante bleiben entscheidend.","terms":[{"term":"pourtant","meaning_de":"dennoch; trotzdem; markiert einen Gegensatz"},{"term":"cependant","meaning_de":"jedoch; allerdings"},{"term":"plutôt","meaning_de":"eher; vielmehr"},{"term":"encore","meaning_de":"noch; wieder; weiterhin, abhängig vom Kontext"},{"term":"déjà","meaning_de":"bereits; schon"},{"term":"peut-être","meaning_de":"vielleicht; möglicherweise"},{"term":"d’ailleurs","meaning_de":"übrigens; außerdem; zudem"},{"term":"même si","meaning_de":"selbst wenn; auch wenn"},{"term":"donc","meaning_de":"also; deshalb; folglich"},{"term":"en revanche","meaning_de":"hingegen; dagegen"},{"term":"performance","meaning_de":"Leistung; Performance abhängig vom Fachkontext"},{"term":"progrès","meaning_de":"Fortschritt; Entwicklung"},{"term":"qualité","meaning_de":"Qualität; Eigenschaft"},{"term":"faiblesse","meaning_de":"Schwäche"},{"term":"évaluation","meaning_de":"Bewertung; Beurteilung"}],"examples":[],"grammar_notes":[],"aliases":["pourtant","cependant","plutôt","encore","déjà","peut-être","d’ailleurs","même si","donc","en revanche","performance","progrès","qualité","faiblesse","évaluation"]}'::jsonb,ARRAY['vocabulary','meaning','context'],'foundational','active','original_authored','messinho_original'),
('ar.lexicon.core',2,'ar','lexicon','Grundwortschatz','Erweiterter kontextbezogener Wortschatz','{"explanation":"Erweiterter, original formulierter Wortschatz mit kontextabhängigen Bedeutungen. Übersetzungen sind Orientierungshilfen; Satzkontext, Register und regionale Variante bleiben entscheidend.","terms":[{"term":"مرحبا","meaning_de":"Hallo; Begrüßung"},{"term":"شكرا","meaning_de":"Danke"},{"term":"من فضلك","meaning_de":"Bitte; höfliche Bitte"},{"term":"لكن","meaning_de":"aber; jedoch"},{"term":"ربما","meaning_de":"vielleicht; möglicherweise"},{"term":"مع ذلك","meaning_de":"trotzdem; dennoch"},{"term":"اليوم","meaning_de":"heute"},{"term":"غدا","meaning_de":"morgen"},{"term":"لاعب","meaning_de":"Spieler"},{"term":"فريق","meaning_de":"Mannschaft; Team"},{"term":"قوة","meaning_de":"Stärke; Kraft"},{"term":"مهارة","meaning_de":"Fähigkeit; Fertigkeit"},{"term":"تطور","meaning_de":"Entwicklung; Fortschritt"},{"term":"تقييم","meaning_de":"Bewertung; Einschätzung"},{"term":"أداء","meaning_de":"Leistung; Performance"}],"examples":[],"grammar_notes":[],"aliases":["مرحبا","شكرا","من فضلك","لكن","ربما","مع ذلك","اليوم","غدا","لاعب","فريق","قوة","مهارة","تطور","تقييم","أداء"]}'::jsonb,ARRAY['vocabulary','meaning','context'],'foundational','active','original_authored','messinho_original'),
('ar-tn.lexicon.core',2,'ar-tn','lexicon','Grundwortschatz','Erweiterter kontextbezogener Wortschatz','{"explanation":"Erweiterter, original formulierter Wortschatz mit kontextabhängigen Bedeutungen. Übersetzungen sind Orientierungshilfen; Satzkontext, Register und regionale Variante bleiben entscheidend.","terms":[{"term":"عسلامة / aslema","meaning_de":"Hallo; tunesische Begrüßung"},{"term":"لاباس / labes","meaning_de":"Alles gut?; mir geht es gut, je nach Kontext"},{"term":"شنوة / chnowa","meaning_de":"Was?; welche Sache?"},{"term":"علاش / alech","meaning_de":"Warum?; aus welchem Grund?"},{"term":"برشا / barcha","meaning_de":"viel; sehr; eine große Menge oder Intensität"},{"term":"ياسر / yesser","meaning_de":"sehr; viel, abhängig vom Satz"},{"term":"فما / fama","meaning_de":"es gibt; vorhanden sein"},{"term":"توا / taw","meaning_de":"jetzt; gerade eben oder gleich, je nach Kontext"},{"term":"وين / win","meaning_de":"wo?; Ortsfrage"},{"term":"قداش / 9addech","meaning_de":"wie viel?; wie viele?"},{"term":"مريقل / mrigel","meaning_de":"gut; in Ordnung; passt"},{"term":"باهي / behi","meaning_de":"gut; okay; schön, je nach Situation"}],"examples":[],"grammar_notes":[],"aliases":["عسلامة / aslema","لاباس / labes","شنوة / chnowa","علاش / alech","برشا / barcha","ياسر / yesser","فما / fama","توا / taw","وين / win","قداش / 9addech","مريقل / mrigel","باهي / behi"]}'::jsonb,ARRAY['vocabulary','meaning','context'],'foundational','active','original_authored','messinho_original'),
('es.lexicon.core',2,'es','lexicon','Grundwortschatz','Erweiterter kontextbezogener Wortschatz','{"explanation":"Erweiterter, original formulierter Wortschatz mit kontextabhängigen Bedeutungen. Übersetzungen sind Orientierungshilfen; Satzkontext, Register und regionale Variante bleiben entscheidend.","terms":[{"term":"aunque","meaning_de":"obwohl; auch wenn"},{"term":"sin embargo","meaning_de":"jedoch; dennoch"},{"term":"todavía","meaning_de":"noch; weiterhin"},{"term":"ya","meaning_de":"bereits; schon; jetzt, je nach Kontext"},{"term":"quizás","meaning_de":"vielleicht; möglicherweise"},{"term":"más bien","meaning_de":"eher; vielmehr"},{"term":"por tanto","meaning_de":"deshalb; folglich"},{"term":"aun así","meaning_de":"trotzdem; dennoch"},{"term":"mientras","meaning_de":"während; solange"},{"term":"sino","meaning_de":"sondern; folgt häufig auf eine Verneinung"},{"term":"rendimiento","meaning_de":"Leistung; Ertrag abhängig vom Kontext"},{"term":"desarrollo","meaning_de":"Entwicklung"},{"term":"fortaleza","meaning_de":"Stärke; positive Fähigkeit"},{"term":"debilidad","meaning_de":"Schwäche"},{"term":"evaluación","meaning_de":"Bewertung; Beurteilung"}],"examples":[],"grammar_notes":[],"aliases":["aunque","sin embargo","todavía","ya","quizás","más bien","por tanto","aun así","mientras","sino","rendimiento","desarrollo","fortaleza","debilidad","evaluación"]}'::jsonb,ARRAY['vocabulary','meaning','context'],'foundational','active','original_authored','messinho_original')
